import * as THREE from 'three';
import {createToyKit,disposeToyTree} from '../world/toy-kit.js';
import {PASS_RADIUS,PASS_FLOOR} from './passing-model.js';
export function createPassingView(parent){const root=new THREE.Group();root.name='sportsField.passing';parent.add(root);const kit=createToyKit(root);let disposed=false;
 kit.box(7.8,.014,3.15,'#bbc9a0',0,PASS_FLOOR-.012,3.8,.08);for(const z of[2.3,5.3])kit.box(7.7,.009,.03,'#fff4d8',0,.067,z,.004);for(const x of[-3.83,3.83])kit.box(.03,.009,3,'#fff4d8',x,.067,3.8,.004);
 const ring=(color,radius=.4)=>{const mesh=new THREE.Mesh(new THREE.RingGeometry(radius-.045,radius,40),new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide,transparent:true,opacity:.9,depthWrite:false}));mesh.rotation.x=-Math.PI/2;mesh.position.y=.071;root.add(mesh);return mesh;};
 const receive=ring('#deb543'),partner=ring('#7194a0',.63);receive.name='passing.receive';receive.visible=false;
 const ball=kit.sphere(PASS_RADIUS,'#87cab5',0,1,0);ball.name='passing.ball';for(const angle of[0,Math.PI/2]){const seam=new THREE.Mesh(new THREE.TorusGeometry(PASS_RADIUS+.001,.006,5,32),new THREE.MeshStandardMaterial({color:'#fff5df',roughness:.9}));seam.rotation.y=angle;ball.add(seam);}
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.25,24),new THREE.MeshBasicMaterial({color:'#526144',transparent:true,opacity:.12,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.074;root.add(shadow);
 const posts=[];for(let i=0;i<2;i++){const group=new THREE.Group();group.name='passing.foam-post.'+i;root.add(group);kit.cylinder(.22,.22,1.45,i?'#b99b87':'#bd9286',0,.785,0,group);kit.sphere(.22,i?'#b99b87':'#bd9286',0,1.51,0,1,.65,1,group);kit.cylinder(.22,.22,.06,'#789285',0,.09,0,group);kit.box(.45,.16,.055,'#f1ddb0',0,1.12,.222,.04,group);posts.push(group);}
 const positions=new Float32Array(768),geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setDrawRange(0,0);const trail=new THREE.Line(geometry,new THREE.LineDashedMaterial({color:'#456d5b',dashSize:.10,gapSize:.075}));trail.frustumCulled=false;trail.name='passing.preview';root.add(trail);const impact=ring('#668578',.18);impact.name='passing.impact';

 function update(s,prediction){ball.position.set(s.position.x,s.position.y,s.position.z);ball.rotation.z=s.elapsed*2.5;shadow.position.set(s.position.x,.074,s.position.z);shadow.material.opacity=.16/(1+s.position.y);partner.position.set(s.turtle.x,.073,s.turtle.z);receive.visible=!!s.receiveSpot;if(s.receiveSpot)receive.position.set(s.receiveSpot.x,.075,s.receiveSpot.z);receive.material.color.set(s.success?'#66906e':'#deb543');for(let i=0;i<posts.length;i++){posts[i].visible=!!s.posts[i];if(s.posts[i])posts[i].position.set(s.posts[i].x,0,s.posts[i].z);}trail.visible=s.phase==='aiming';impact.visible=s.phase==='aiming'&&!!prediction?.event;if(prediction){const count=Math.min(256,prediction.points.length);for(let i=0;i<count;i++){positions[i*3]=prediction.points[i].x;positions[i*3+1]=prediction.points[i].y;positions[i*3+2]=prediction.points[i].z;}geometry.attributes.position.needsUpdate=true;geometry.setDrawRange(0,count);trail.computeLineDistances();trail.material.color.set(prediction.event?.type==='turtle-catch'?'#4b8260':'#b17856');impact.position.set(prediction.position.x,.079,prediction.position.z);}}
 return{root,ball,posts,trail,receive,update,dispose(){if(disposed)return;disposed=true;disposeToyTree(root);}};
}
